 scoreValue,IsAbstain isAbstain,FileID fileId,SortOrder sortOrder FROM SafetyVote_Options WHERE QuestionID=? AND Status='Active' ORDER BY SortOrder,id",[$q['id']]);foreach($q['options']as&$o){$o['isAbstain']=(bool)$o['isAbstain'];$o['scoreValue']=$o['scoreValue']===null?null:(float)$o['scoreValue'];$o['media']=array_values(array_filter($media,fn($m)=>$m['scopeType']==='option'&&$m['questionCode']===$q['questionCode']&&$m['optionCode']===$o['optionCode']));}unset($o);}unset($q);return$qs;}
