function sv3_eligibility_origin(?string$source,bool$eligible,bool$discoveryOnly=false):?string{if(!$eligible)return$discoveryOnly?'public_listing':null;$source=strtolower(trim((string)$source));if($source==='automatic_rule_match')return'automatic_rule_match';if(in_array($source,['eligibility_amendment','manual_apply','admin_approval'],true))return'admin_amendment';return'initial_snapshot';}
