function sv3_own_responses(array$c,string$employee):array{if(!in_array($c['PrivacyMode'],['identified','confidential'],true))return[];global$config;$rows=db_rows("SELECT b.id BallotID,b.BallotSequence,b.SubmittedAt,q.id QuestionID,q.Title,q.QuestionType,o.Label OptionLabel,o.FileID OptionFileID,a.RankValue,a.NumericValue,a.BooleanValue,a.TextValueEncrypted,a.DateTimeValue,a.FileID,a.AnswerOrder FROM SafetyVote_BallotIdentities bi JOIN SafetyVote_Ballots b ON b.id=bi.BallotID JOIN SafetyVote_BallotAnswers a ON a.BallotID=b.id JOIN SafetyVote_Questions q ON q.id=a.QuestionID LEFT JOIN SafetyVote_Options o ON o.id=a.OptionID WHERE bi.EmployeeID=? AND b.CampaignVersionID=? AND b.Status='Accepted' ORDER BY b.SubmittedAt DESC,b.id DESC,q.SortOrder,a.AnswerOrder,a.id",[$employee,$c['CurrentVersionID']]);$out=[];$ballots=[];foreach($rows as$row){$bid=(int)$row['BallotID'];if(!isset($ballots[$bid])){$out[]=['ballotSequence'=>(int)$row['BallotSequence'],'submittedAt'=>$row['SubmittedAt'],'questions'=>[]];$ballots[$bid]=count($out)-1;}$ai=$ballots[$bid];$qid=(int)$row['QuestionID'];$qi=null;foreach($out[$ai]['questions']as$i=>$question)if((int)$question['questionId']===$qid){$qi=$i;break;}if($qi===null){$out[$ai]['questions'][]=['questionId'=>$qid,'title'=>$row['Title'],'questionType'=>$row['QuestionType'],'answers'=>[]];$qi=count($out[$ai]['questions'])-1;}$out[$ai]['questions'][$qi]['answers'][]=['optionLabel'=>$row['OptionLabel']?:null,'optionImageFileId'=>$row['OptionFileID']===null?null:(int)$row['OptionFileID'],'rankValue'=>$row['RankValue']===null?null:(int)$row['RankValue'],'numericValue'=>$row['NumericValue']===null?null:(float)$row['NumericValue'],'booleanValue'=>$row['BooleanValue']===null?null:(bool)$row['BooleanValue'],'textValue'=>$row['TextValueEncrypted']?sv3_decrypt((string)$row['TextValueEncrypted'],(string)$config['jwt_secret']):null,'dateTimeValue'=>$row['DateTimeValue']?:null,'fileAttached'=>!empty($row['FileID']),'answerOrder'=>(int)$row['AnswerOrder']];}